using namespace std;

class Solution {
public:
    long long minimumCost(vector<int>& nums, vector<int>& cost, int k) {
        int n = nums.size();
        vector<long long> prefixNums(n + 1, 0);
        vector<long long> prefixCost(n + 1, 0);

        for (int i = 0; i < n; ++i) {
            prefixNums[i + 1] = prefixNums[i] + nums[i];
            prefixCost[i + 1] = prefixCost[i] + cost[i];
        }

        vector<long long> dp(n + 1, LLONG_MAX);
        dp[n] = 0;

        for (int i = n - 1; i >= 0; --i) {
            long long remCost = prefixCost[n] - prefixCost[i];
            for (int j = i; j < n; ++j) {
                long long curNums = prefixNums[j + 1];
                long long curCost = prefixCost[j + 1] - prefixCost[i];
                long long cand = curNums * curCost + (long long)k * remCost + dp[j + 1];
                dp[i] = min(dp[i], cand);
            }
        }

        return dp[0];
    }
};

import java.util.*;

class Solution {
    public long minimumCost(int[] nums, int[] cost, int k) {
        int n = nums.length;
        long[] prefixNums = new long[n + 1];
        long[] prefixCost = new long[n + 1];

        for (int i = 0; i < n; i++) {
            prefixNums[i + 1] = prefixNums[i] + nums[i];
            prefixCost[i + 1] = prefixCost[i] + cost[i];
        }

        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE);
        dp[n] = 0;

        for (int i = n - 1; i >= 0; i--) {
            long remCost = prefixCost[n] - prefixCost[i];
            for (int j = i; j < n; j++) {
                long curNums = prefixNums[j + 1];
                long curCost = prefixCost[j + 1] - prefixCost[i];
                long cand = curNums * curCost + (long) k * remCost + dp[j + 1];
                dp[i] = Math.min(dp[i], cand);
            }
        }

        return dp[0];
    }
}

var minimumCost = function(nums, cost, k) {
    const n = nums.length;
    const prefixNums = new Array(n + 1).fill(0n);
    const prefixCost = new Array(n + 1).fill(0n);

    for (let i = 0; i < n; i++) {
        prefixNums[i + 1] = prefixNums[i] + BigInt(nums[i]);
        prefixCost[i + 1] = prefixCost[i] + BigInt(cost[i]);
    }

    const dp = new Array(n + 1).fill(null);
    dp[n] = 0n;

    const kBig = BigInt(k);

    for (let i = n - 1; i >= 0; i--) {
        const remCost = prefixCost[n] - prefixCost[i];
        for (let j = i; j < n; j++) {
            const curNums = prefixNums[j + 1];
            const curCost = prefixCost[j + 1] - prefixCost[i];
            const cand = curNums * curCost + kBig * remCost + dp[j + 1];
            if (dp[i] === null || cand < dp[i]) {
                dp[i] = cand;
            }
        }
    }

    return Number(dp[0]);
};
